def lps(s):
    n = len(s)
    # dp[i][j] will store LPS length of s[i..j]
    dp = [[0] * n for _ in range(n)]

    # Length 1 subsequences (single characters are palindromes)
    for i in range(n):
        dp[i][i] = 1

    # Fill DP table by substring length from 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    return dp[0][n - 1]


